def blockDiagonalHistory (c : ℕ → NormalizedBlockSystem 𝕜) : ℕ → Finset ℕ :=
  Nat.rec ∅ (fun n H => H ∪ (Finset.range (n + 1)).biUnion
    (fun m => (blockIteration c m (n - m)).support (H.sup id + 1)))

